import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.Cdp8-jB6.js";const g=JSON.parse('{"title":"Image sources to integrate (2026-07-06)","description":"","frontmatter":{},"headers":[],"relativePath":"wip/image-sources-to-add.md","filePath":"wip/image-sources-to-add.md"}'),s={name:"wip/image-sources-to-add.md"};function i(n,e,c,d,l,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="image-sources-to-integrate-2026-07-06" tabindex="-1">Image sources to integrate (2026-07-06) <a class="header-anchor" href="#image-sources-to-integrate-2026-07-06" aria-label="Permalink to &quot;Image sources to integrate (2026-07-06)&quot;">​</a></h1><p>First-party / official image sources Marko found during the off-subject re-source effort. These beat Commons keyword-search (which poisoned <code>juice</code> → orange juice). Goal: add each as a <strong>primary source adapter</strong> in <code>scripts/agency-mission-sources.ts</code> (currently NASA-API only → else Commons), tried BEFORE the Commons failover, filtered by the new fetch quality-gate.</p><h2 id="the-sources" tabindex="-1">The sources <a class="header-anchor" href="#the-sources" aria-label="Permalink to &quot;The sources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>URL</th><th>Access</th><th>License (VERIFY per-image)</th><th>Best for</th></tr></thead><tbody><tr><td><strong>NASA on Unsplash</strong></td><td><a href="https://unsplash.com/@nasa" target="_blank" rel="noreferrer">https://unsplash.com/@nasa</a></td><td>Unsplash API</td><td>Unsplash License (free, no attribution required)</td><td>NASA missions, hero-grade</td></tr><tr><td><strong>SpaceX on Unsplash</strong></td><td><a href="https://unsplash.com/@spacex" target="_blank" rel="noreferrer">https://unsplash.com/@spacex</a></td><td>Unsplash API</td><td>Unsplash License</td><td>SpaceX (official moved here)</td></tr><tr><td><strong>SpaceX Flickr</strong></td><td><a href="https://www.flickr.com/photos/spacex/" target="_blank" rel="noreferrer">https://www.flickr.com/photos/spacex/</a></td><td>Flickr API</td><td>SpaceX releases <strong>CC0 / public domain</strong></td><td>SpaceX launches, hardware</td></tr><tr><td><strong>NASA galleries</strong></td><td><a href="https://www.nasa.gov/gallery/" target="_blank" rel="noreferrer">https://www.nasa.gov/gallery/</a></td><td>HTML scrape</td><td><strong>Public domain</strong> (US Gov)</td><td>recent missions (e.g. blue-origin-blue-moon-mark-1), KSC/shuttle history (ksc-history)</td></tr><tr><td><strong>ESA photo library</strong></td><td><a href="https://photolibrary.esa.int/albums/" target="_blank" rel="noreferrer">https://photolibrary.esa.int/albums/</a></td><td>HTML scrape / API?</td><td>ESA standard (usually <strong>CC BY-SA 3.0 IGO</strong> — attribution)</td><td>ESA missions (JUICE, Rosetta, Mars Express, BepiColombo, ...)</td></tr></tbody></table><p>Marko-flagged standouts: <code>nasa.gov/gallery/blue-origin-blue-moon-mark-1/</code>, <code>nasa.gov/gallery/ksc-history/</code> (spectacular shuttle imagery).</p><h2 id="licensing-—-the-gating-concern-the-pipeline-enforces-cc-pd-credit-no-watermark" tabindex="-1">Licensing — the gating concern (the pipeline enforces CC/PD + credit + no-watermark) <a class="header-anchor" href="#licensing-—-the-gating-concern-the-pipeline-enforces-cc-pd-credit-no-watermark" aria-label="Permalink to &quot;Licensing — the gating concern (the pipeline enforces CC/PD + credit + no-watermark)&quot;">​</a></h2><ul><li><strong>NASA gov / NASA-on-Unsplash</strong>: public domain / free — cleanest.</li><li><strong>SpaceX Flickr</strong>: SpaceX explicitly releases CC0 — cleanest.</li><li><strong>SpaceX/NASA on Unsplash</strong>: the <em>Unsplash License</em> is permissive (free, no attribution required) but is NOT strictly CC0/PD — confirm it clears the pipeline&#39;s CC/PD bar (<code>validate-data</code> license allowlist) before shipping, and record the right <code>license_short</code>/<code>license_url</code> in provenance.</li><li><strong>ESA photo library</strong>: usually CC BY-SA 3.0 IGO → attribution REQUIRED; must land the ESA credit in provenance + on /credits.</li></ul><p>Every adapter must return, per image: <code>image_url</code>, <code>title</code>, <code>author/credit</code>, <code>license_short</code>, <code>license_url</code>, <code>source_url</code>. No credit → don&#39;t land it.</p><h2 id="integration-approach-reusable-adapters" tabindex="-1">Integration approach (reusable adapters) <a class="header-anchor" href="#integration-approach-reusable-adapters" aria-label="Permalink to &quot;Integration approach (reusable adapters)&quot;">​</a></h2><ol><li>Extend <code>AgencyPrimarySourceTag</code> + <code>fetchAgencyPrimaryImageUrls</code> with per-source adapters. Each takes <code>{ missionId, agency, name/target }</code> → candidate list.</li><li>Order of preference per mission/agency (extend <code>WIKIMEDIA_*_FALLBACK</code> idea): agency-official (NASA gov / ESA portal) → agency-Unsplash/Flickr → Commons.</li><li>All candidates flow through the <strong>fetch quality-gate</strong> (score-and-reject infographics/diagrams/people/off-subject) already wired into <code>fill-gallery-gaps</code> — so a bad official image is still dropped.</li><li>API keys: Unsplash + Flickr need app keys (add to <code>.env</code>; document in the image-pipeline guide). NASA gov + ESA are scrapes (fragile — pin selectors + snapshot-test).</li></ol><h2 id="suggested-priority" tabindex="-1">Suggested priority <a class="header-anchor" href="#suggested-priority" aria-label="Permalink to &quot;Suggested priority&quot;">​</a></h2><ol><li><strong>Unsplash (NASA + SpaceX)</strong> and <strong>SpaceX Flickr</strong> — clean public APIs + permissive licenses → highest value, lowest effort. Covers SpaceX + modern NASA.</li><li><strong>NASA galleries</strong> scrape — public domain, great for recent missions + KSC history.</li><li><strong>ESA photo library</strong> — the ESA-mission fix (JUICE, Rosetta, ...); scrape + CC BY-SA attribution handling.</li></ol><p>Each is a self-contained adapter = a permanent investment, reused by every future fetch + the 98-image re-source batch.</p>',13)])])}const u=t(s,[["render",i]]);export{g as __pageData,u as default};
